'use server'

import { refresh } from 'next/cache'

let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<boolean> {
  notificationsEnabled = enabled
  refresh()
  return notificationsEnabled
}

export async function toggleNotificationPreference(
  valueOrFormData?: boolean | FormData | unknown
): Promise<boolean> {
  if (typeof valueOrFormData === 'boolean') {
    notificationsEnabled = valueOrFormData
  } else if (
    valueOrFormData &&
    typeof (valueOrFormData as { get?: unknown }).get === 'function' &&
    (valueOrFormData as FormData).get('enabled') !== null
  ) {
    const val = (valueOrFormData as FormData).get('enabled')
    notificationsEnabled = val === 'true' || val === 'on' || val === '1'
  } else {
    notificationsEnabled = !notificationsEnabled
  }

  refresh()
  return notificationsEnabled
}

export async function toggleNotifications(
  valueOrFormData?: boolean | FormData | unknown
): Promise<boolean> {
  return toggleNotificationPreference(valueOrFormData)
}

export async function toggleNotification(
  valueOrFormData?: boolean | FormData | unknown
): Promise<boolean> {
  return toggleNotificationPreference(valueOrFormData)
}

export async function togglePreference(
  valueOrFormData?: boolean | FormData | unknown
): Promise<boolean> {
  return toggleNotificationPreference(valueOrFormData)
}

