import { refresh } from 'next/cache'
import {
  toggleNotificationPreference,
  getNotificationPreference,
  setNotificationPreference,
  toggleNotifications,
} from '@/app/actions'

describe('Notification preference server action', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('toggles preference from false to true and calls refresh', async () => {
    await setNotificationPreference(false)
    vi.clearAllMocks()

    const newState = await toggleNotificationPreference()
    expect(newState).toBe(true)
    expect(await getNotificationPreference()).toBe(true)
    expect(refresh).toHaveBeenCalledTimes(1)
  })

  it('toggles preference from true to false and calls refresh', async () => {
    const newState = await toggleNotificationPreference()
    expect(newState).toBe(false)
    expect(await getNotificationPreference()).toBe(false)
    expect(refresh).toHaveBeenCalledTimes(1)
  })

  it('works with aliases like toggleNotifications', async () => {
    await setNotificationPreference(false)
    vi.clearAllMocks()

    const newState = await toggleNotifications()
    expect(newState).toBe(true)
    expect(refresh).toHaveBeenCalledTimes(1)
  })
})

